import { parsePublicKey, verifySignature } from '@ohmyopensource/ohmyupdater-core';
import { describe, expect, it } from 'vitest';
import { generateKeyPair, KeyError, readSecretKey, signMessage } from './keys.js';

// Throwaway key pair generated by the official minisign 0.12 with the password
// "test-password" and the default (1 GiB) scrypt limits. Never used for real releases.
const MINISIGN_SECRET_KEY = `untrusted comment: minisign encrypted secret key
RWRTY0IyloRckS4urozq5Yb/Un0swyZdIoF+ilej46IXVcdbCTkAAAACAAAAAAAAAEAAAAAA63w/pULYnuHgIVvK8JYNSDhQM1JvYfYT8FI8W6pFTitZeGmHJ1ngfgn481kTH2XG5pb2TLlvBsE/miihtPmFQ+BkkLxc1oIWcPVUCiAvVRsv4825F/A1bQ2GMVzcvXQAzBUx5zXGMfY=
`;
const MINISIGN_PUBLIC_KEY = `untrusted comment: minisign public key 4CF30AA95788EB14
RWQU64hXqQrzTFHHSzpIgsei180LD+A5zAARdlLvd0IWNuVJnv0EqxRW
`;

// Low scrypt limits keep the tests fast. Real keys use the minisign defaults.
const FAST = { opslimit: 1048576, memlimit: 16777216 };
const message = new TextEncoder().encode('{"schemaVersion":1}\n');

describe('keys', () => {
  it('signs with a key generated by the official minisign', () => {
    const key = readSecretKey(MINISIGN_SECRET_KEY, 'test-password');
    const signature = signMessage(message, key, 'compatibility test');
    expect(verifySignature(message, signature, [parsePublicKey(MINISIGN_PUBLIC_KEY)])).toEqual({
      keyId: '4CF30AA95788EB14',
      trustedComment: 'compatibility test',
    });
  }, 30_000);

  it('rejects a wrong password', () => {
    expect(() => readSecretKey(MINISIGN_SECRET_KEY, 'wrong-password')).toThrow(KeyError);
  }, 30_000);

  it('generates encrypted keys that round-trip through the core verifier', () => {
    const pair = generateKeyPair('secret', FAST);
    const key = readSecretKey(pair.secretKeyFile, 'secret');
    const result = verifySignature(message, signMessage(message, key, 'ok'), [
      parsePublicKey(pair.publicKeyFile),
    ]);
    expect(result.keyId).toBe(pair.keyId);
    expect(pair.secretKeyFile).toContain('encrypted secret key');
  });

  it('requires the password for encrypted keys', () => {
    const pair = generateKeyPair('secret', FAST);
    expect(() => readSecretKey(pair.secretKeyFile, undefined)).toThrow(KeyError);
  });

  it('supports unencrypted throwaway keys', () => {
    const pair = generateKeyPair(undefined, FAST);
    const key = readSecretKey(pair.secretKeyFile, undefined);
    expect(() =>
      verifySignature(message, signMessage(message, key, 'ok'), [
        parsePublicKey(pair.publicKeyFile),
      ]),
    ).not.toThrow();
  });

  it('generates a different key every time', () => {
    expect(generateKeyPair(undefined, FAST).keyId).not.toBe(generateKeyPair(undefined, FAST).keyId);
  });

  it('rejects multi-line trusted comments', () => {
    const key = readSecretKey(generateKeyPair(undefined, FAST).secretKeyFile, undefined);
    expect(() => signMessage(message, key, 'line one\nline two')).toThrow(KeyError);
  });

  it('rejects input that is not a secret key', () => {
    expect(() => readSecretKey('not a key', 'secret')).toThrow(KeyError);
    expect(() => readSecretKey(MINISIGN_PUBLIC_KEY, 'secret')).toThrow(KeyError);
  });
});
